/*
 * Occupancy-based entity control
 *
 * Expected msg properties:
 *   msg.entityid
 *   msg.sensor                 Optional if SENSOR contains the entity ID
 *   msg.min_absence            Seconds
 *   msg.min_on_time            Seconds
 *   msg.x_minutes              History window in minutes
 *   msg.is_dark_lux            Optional lux threshold
 *   msg.payload                Home Assistant history array when applicable
 *
 * Environment variables:
 *   PRESENCE                   TOTAL, LONGEST, AVG, or LAST
 *   SENSOR                     Sensor entity ID, true/false, or blank
 *   DEBUG                      true/false, 1/0, yes/no, on/off
 *   NODE_RED_USER_ID           Optional Node-RED Home Assistant user ID
 */

const DEFAULT_NODE_RED_USER_ID =
  "e7ab148881b7499f9b3189442f4e473c";

const PRESENCE_STATES = new Set([
  "on",
  "detected",
  "true",
  "home",
  "occupied",
  "present"
]);

const INVALID_STATES = new Set([
  "unknown",
  "unavailable",
  "none",
  "null",
  ""
]);

function envString(name, fallback = "") {
  const value = env.get(name);

  if (value === undefined || value === null) {
    return fallback;
  }

  return String(value).trim();
}

function envBoolean(name, fallback = false) {
  const value = env.get(name);

  if (value === undefined || value === null || value === "") {
    return fallback;
  }

  if (typeof value === "boolean") {
    return value;
  }

  const normalized = String(value).trim().toLowerCase();

  if (["true", "1", "yes", "on"].includes(normalized)) {
    return true;
  }

  if (["false", "0", "no", "off"].includes(normalized)) {
    return false;
  }

  return fallback;
}

function finiteNumber(value, fallback = 0, minimum = null) {
  const number = Number(value);

  if (!Number.isFinite(number)) {
    return fallback;
  }

  if (minimum !== null && number < minimum) {
    return minimum;
  }

  return number;
}

function secondsSince(timestamp, currentTime) {
  const timestampMs = Date.parse(timestamp);

  if (!Number.isFinite(timestampMs)) {
    return null;
  }

  // Avoid negative durations if clocks are slightly out of sync.
  return Math.max(0, (currentTime - timestampMs) / 1000);
}

function convertSecondsToWords(totalSeconds) {
  const value = Number(totalSeconds);

  if (!Number.isFinite(value) || value <= 0) {
    return "0 seconds";
  }

  const roundedSeconds = Math.floor(value);
  const minutes = Math.floor(roundedSeconds / 60);
  const seconds = roundedSeconds % 60;

  const parts = [];

  if (minutes > 0) {
    parts.push(
      `${minutes} ${minutes === 1 ? "minute" : "minutes"}`
    );
  }

  if (seconds > 0) {
    parts.push(
      `${seconds} ${seconds === 1 ? "second" : "seconds"}`
    );
  }

  return parts.join(" and ") || "0 seconds";
}

function appendDescription(text) {
  if (!text) {
    return;
  }

  msg.descr = msg.descr
    ? `${msg.descr.trim()} ${text.trim()}`
    : text.trim();
}

function debugLog(message, details) {
  if (!DEBUG) {
    return;
  }

  if (details === undefined) {
    node.warn(message);
  } else {
    node.warn({
      message,
      details
    });
  }
}

function failSafe(message, details) {
  msg.action = "leave";
  msg.error = message;

  appendDescription(`Unable to evaluate automation safely: ${message}.`);

  if (details !== undefined) {
    msg.error_details = details;
  }

  // Passing msg allows a connected Catch node to retain the original message.
  node.error(message, msg);

  return msg;
}

function getHaEntity(states, entityId) {
  if (!entityId || typeof entityId !== "string") {
    return null;
  }

  return states[entityId] || null;
}

function normalizeState(value) {
  if (value === undefined || value === null) {
    return "";
  }

  return String(value).trim().toLowerCase();
}

function isPresenceState(value) {
  return PRESENCE_STATES.has(normalizeState(value));
}

function calculatePresence(history, windowStart, currentTime, mode) {
  if (!Array.isArray(history)) {
    throw new Error(
      "Expected a Home Assistant history array in msg.payload"
    );
  }

  const records = [];

  /*
   * Normalize the history once. Records after "now" are ignored.
   * Sorting remains necessary because HA history is not assumed to be ordered.
   */
  for (const item of history) {
    if (!item || typeof item !== "object") {
      continue;
    }

    const timestamp = item.last_changed || item.last_updated;
    const timestampMs = Date.parse(timestamp);

    if (!Number.isFinite(timestampMs) || timestampMs > currentTime) {
      continue;
    }

    records.push({
      state: normalizeState(item.state),
      ts: timestampMs
    });
  }

  records.sort((a, b) => a.ts - b.ts);

  /*
   * Determine the state at the beginning of the requested window.
   * If no earlier state is available, default to off.
   */
  let stateAtWindowStart = "off";
  let firstWindowRecordIndex = records.length;

  for (let index = 0; index < records.length; index += 1) {
    const record = records[index];

    if (record.ts <= windowStart) {
      stateAtWindowStart = record.state;
    } else {
      firstWindowRecordIndex = index;
      break;
    }
  }

  const intervals = [];
  let currentState = stateAtWindowStart;
  let intervalStart = windowStart;

  /*
   * Walk only the records that occur inside the requested window.
   */
  for (
    let index = firstWindowRecordIndex;
    index < records.length;
    index += 1
  ) {
    const record = records[index];

    if (record.ts < windowStart) {
      continue;
    }

    if (isPresenceState(currentState) && record.ts > intervalStart) {
      intervals.push(record.ts - intervalStart);
    }

    currentState = record.state;
    intervalStart = Math.max(record.ts, windowStart);
  }

  /*
   * Close the final interval at the current time.
   */
  if (isPresenceState(currentState) && currentTime > intervalStart) {
    intervals.push(currentTime - intervalStart);
  }

  if (intervals.length === 0) {
    return {
      milliseconds: 0,
      count: 0
    };
  }

  let milliseconds = 0;

  switch (mode) {
    case "TOTAL":
      milliseconds = intervals.reduce(
        (sum, duration) => sum + duration,
        0
      );
      break;

    case "LONGEST":
      milliseconds = Math.max(...intervals);
      break;

    case "AVG":
      milliseconds =
        intervals.reduce(
          (sum, duration) => sum + duration,
          0
        ) / intervals.length;
      break;

    case "LAST":
      milliseconds = intervals[intervals.length - 1];
      break;

    default:
      throw new Error(
        `Unsupported PRESENCE mode "${mode}"`
      );
  }

  return {
    milliseconds,
    count: intervals.length
  };
}


/* ------------------------------------------------------------------
 * Configuration
 * ------------------------------------------------------------------ */

const NOW = Date.now();
const DEBUG = envBoolean("DEBUG", false);

const requestedPresenceMode =
  envString("PRESENCE", "TOTAL").toUpperCase();

const validPresenceModes = new Set([
  "TOTAL",
  "LONGEST",
  "AVG",
  "LAST"
]);

const presenceMode = validPresenceModes.has(requestedPresenceMode)
  ? requestedPresenceMode
  : "TOTAL";

if (requestedPresenceMode !== presenceMode) {
  node.warn(
    `Invalid PRESENCE value "${requestedPresenceMode}". ` +
    "Defaulting to TOTAL."
  );
}

const sensorEnvironmentValue = envString("SENSOR", "");
const nodeRedUserId =
  envString("NODE_RED_USER_ID", DEFAULT_NODE_RED_USER_ID);

msg.action = "leave";
msg.descr = "";

if (
  msg.reason !== undefined &&
  msg.reason !== null &&
  String(msg.reason).trim() !== ""
) {
  msg.descr = `${String(msg.reason).trim()} `;
}


/* ------------------------------------------------------------------
 * Validate Home Assistant global context
 * ------------------------------------------------------------------ */

try {
  const haGlobal = global.get("homeassistant");
  const homeAssistant = haGlobal && haGlobal.homeAssistant;
  const states = homeAssistant && homeAssistant.states;

  if (!states || typeof states !== "object") {
    return failSafe(
      "Home Assistant global state is unavailable. " +
      "Verify that global context is enabled on the Home Assistant server node"
    );
  }

  const entityId =
    typeof msg.entityid === "string"
      ? msg.entityid.trim()
      : "";

  if (!entityId) {
    return failSafe("msg.entityid is missing or invalid");
  }

  const entity = getHaEntity(states, entityId);

  if (!entity) {
    return failSafe(
      `Home Assistant entity "${entityId}" was not found`
    );
  }

  msg.entityid = entityId;
  msg.currently = normalizeState(entity.state);

  const context = entity.context || {};
  msg.fullauto = context.user_id === nodeRedUserId;

  /*
   * Normalize all timing values once.
   */
  msg.min_absence = finiteNumber(msg.min_absence, 0, 0);
  msg.min_on_time = finiteNumber(msg.min_on_time, 0, 0);
  msg.x_minutes = finiteNumber(msg.x_minutes, 10, 0);

  /*
   * If the device was manually activated, double the configured times.
   */
  if (!msg.fullauto) {
    msg.min_absence *= 2;
    msg.min_on_time *= 2;

    if (msg.min_absence === 0) {
      msg.min_absence = 10 * 60;
    }

    if (msg.min_on_time === 0) {
      msg.min_on_time = 10 * 60;
    }
  }

  const onForSeconds = secondsSince(entity.last_changed, NOW);

  if (onForSeconds === null) {
    return failSafe(
      `Entity "${entityId}" has an invalid last_changed timestamp`,
      entity.last_changed
    );
  }

  msg.on_for_seconds =
    msg.currently === "on" ? onForSeconds : 0;

  debugLog("Entity evaluation started", {
    entityId: msg.entityid,
    state: msg.currently,
    fullauto: msg.fullauto,
    onForSeconds: msg.on_for_seconds,
    minOnTime: msg.min_on_time,
    minAbsence: msg.min_absence
  });


  /* --------------------------------------------------------------
   * Entity is already off
   * -------------------------------------------------------------- */

  if (msg.currently !== "on") {
    msg.currently = "off";
    msg.on_for_seconds = 0;
    appendDescription(`Leaving ${msg.entityid} off.`);

    return msg;
  }


  /* --------------------------------------------------------------
   * Determine whether a motion/occupancy sensor is configured
   * -------------------------------------------------------------- */

  let sensorId = "";

  if (
    typeof msg.sensor === "string" &&
    msg.sensor.trim() !== ""
  ) {
    sensorId = msg.sensor.trim();
  } else if (
    sensorEnvironmentValue.includes(".") &&
    !["true", "false", "yes", "no", "on", "off", "1", "0"]
      .includes(sensorEnvironmentValue.toLowerCase())
  ) {
    /*
     * SENSOR may contain the actual entity ID.
     */
    sensorId = sensorEnvironmentValue;
  }

  const sensorFlagEnabled = [
    "true",
    "yes",
    "on",
    "1"
  ].includes(sensorEnvironmentValue.toLowerCase());

  const hasSensor = Boolean(sensorId) || sensorFlagEnabled;

  if (hasSensor && !sensorId) {
    return failSafe(
      "A sensor is enabled, but msg.sensor does not contain a sensor entity ID"
    );
  }


  /* --------------------------------------------------------------
   * Sensor-based automation
   * -------------------------------------------------------------- */

  if (hasSensor) {
    const sensor = getHaEntity(states, sensorId);

    if (!sensor) {
      return failSafe(
        `Occupancy sensor "${sensorId}" was not found`
      );
    }

    msg.sensor = sensorId;

    /*
     * Preserve msg.Occupied if an upstream node intentionally set it.
     * Otherwise use the live HA sensor state.
     */
    let occupiedState =
      msg.Occupied !== undefined &&
        msg.Occupied !== null &&
        String(msg.Occupied).trim() !== ""
        ? normalizeState(msg.Occupied)
        : normalizeState(sensor.state);

    if (INVALID_STATES.has(occupiedState)) {
      return failSafe(
        `Occupancy sensor "${sensorId}" has an invalid state`,
        sensor.state
      );
    }

    msg.Occupied = isPresenceState(occupiedState)
      ? "on"
      : "off";

    const occupancyChangeSeconds =
      secondsSince(sensor.last_changed, NOW);

    if (occupancyChangeSeconds === null) {
      return failSafe(
        `Sensor "${sensorId}" has an invalid last_changed timestamp`,
        sensor.last_changed
      );
    }

    if (msg.Occupied === "on") {
      msg.SecondsofOccupancy = occupancyChangeSeconds;
      msg.SecondsSinceOccupancy = 0;
      msg.OccupancyCount = 1;

      appendDescription(
        `Sensor ${sensorId} indicates the room is occupied.`
      );

      debugLog("Room is currently occupied", {
        sensor: sensorId,
        occupiedForSeconds: occupancyChangeSeconds
      });
    } else {
      msg.SecondsofOccupancy = 0;
      msg.SecondsSinceOccupancy = occupancyChangeSeconds;
      msg.OccupancyCount = 0;

      debugLog("Room is currently unoccupied", {
        sensor: sensorId,
        clearForSeconds: occupancyChangeSeconds
      });

      /*
       * Analyze occupancy history.
       */
      const windowMs = msg.x_minutes * 60 * 1000;
      const windowStart = NOW - windowMs;

      const presenceResult = calculatePresence(
        msg.payload,
        windowStart,
        NOW,
        presenceMode
      );

      /*
       * Clamp the result to the requested history window.
       */
      const presenceMs = Math.min(
        Math.max(0, presenceResult.milliseconds),
        windowMs
      );

      msg.SecondsofOccupancy =
        Math.round(presenceMs / 1000);

      msg.OccupancyCount = presenceResult.count;

      const minimumOnTimeMet =
        msg.min_on_time === 0 ||
        msg.on_for_seconds >= msg.min_on_time;

      const minimumAbsenceMet =
        msg.min_absence === 0 ||
        msg.SecondsSinceOccupancy >= msg.min_absence;

      if (minimumOnTimeMet && minimumAbsenceMet) {
        msg.decision = 218;
        msg.action = "off";

        msg.descr =
          `Turning Off ${msg.entityid}. ` +
          `No motion for ` +
          `${convertSecondsToWords(msg.SecondsSinceOccupancy)}`;

        if (msg.min_on_time > 0) {
          msg.descr +=
            ` and the minimum on time (` +
            `${convertSecondsToWords(msg.min_on_time)}) ` +
            `has been met`;
        }

        if (msg.min_absence > 0) {
          msg.descr +=
            ` and the minimum absence (` +
            `${convertSecondsToWords(msg.min_absence)}) ` +
            `has been met`;
        }

        msg.descr += ".";
      } else {
        msg.decision = 233;
        msg.action = "leave";

        msg.descr =
          `Leaving ${msg.entityid} on. ` +
          `No motion for ` +
          `${convertSecondsToWords(msg.SecondsSinceOccupancy)}`;

        if (!minimumOnTimeMet) {
          msg.descr +=
            ` and the minimum on time (` +
            `${convertSecondsToWords(msg.min_on_time)}) ` +
            `has NOT been met`;
        }

        if (!minimumAbsenceMet) {
          msg.descr +=
            ` and the minimum absence (` +
            `${convertSecondsToWords(msg.min_absence)}) ` +
            `has NOT been met`;
        }

        msg.descr += ".";
      }

      msg.sentence =
        convertSecondsToWords(msg.SecondsofOccupancy);

      appendDescription(
        `${presenceMode} presence was ${msg.sentence}.`
      );
    }

    /*
     * If the room is occupied, explicitly describe why the entity
     * remains on.
     */
    if (
      msg.Occupied === "on" &&
      msg.action === "leave"
    ) {
      msg.descr =
        `Leaving ${msg.entityid} on because the room ` +
        `is currently occupied.`;

      appendDescription(
        `Sensor ${sensorId} has indicated occupancy for ` +
        `${convertSecondsToWords(msg.SecondsofOccupancy)}.`
      );
    }
  }


  /* --------------------------------------------------------------
   * No-sensor automation
   * -------------------------------------------------------------- */

  else {
    debugLog("No occupancy sensor configured");

    msg.sentence =
      convertSecondsToWords(msg.on_for_seconds);

    /*
     * Preserve the original behavior:
     * min_on_time acts as the point at which the device may be
     * turned off when no sensor is configured.
     *
     * A value of zero causes immediate eligibility.
     */
    const maximumOnTimeReached =
      msg.on_for_seconds >= msg.min_on_time;

    if (
      msg.action === "leave" &&
      msg.currently === "on" &&
      maximumOnTimeReached
    ) {
      msg.decision = 274;
      msg.action = "off";

      msg.descr =
        `Turning Off ${msg.entityid} because it has been on ` +
        `for ${msg.sentence}, meeting or exceeding the ` +
        `configured on-time threshold of ` +
        `${convertSecondsToWords(msg.min_on_time)}.`;
    } else {
      msg.decision = 284;
      msg.action = "leave";

      msg.descr =
        `Leaving ${msg.entityid} ${msg.currently} because ` +
        `it has only been ${msg.currently} for ` +
        `${msg.sentence}.`;

      if (msg.min_on_time > 0) {
        appendDescription(
          `It must remain on for at least ` +
          `${convertSecondsToWords(msg.min_on_time)}.`
        );
      }
    }
  }


  /* --------------------------------------------------------------
   * Illuminance override
   * -------------------------------------------------------------- */

  const luxThreshold =
    finiteNumber(msg.is_dark_lux, 0, 0);

  if (
    msg.fullauto &&
    msg.currently === "on" &&
    msg.action === "leave" &&
    luxThreshold > 0
  ) {
    const illuminanceEntityId =
      typeof msg.illuminance_entity === "string" &&
        msg.illuminance_entity.trim() !== ""
        ? msg.illuminance_entity.trim()
        : "sensor.illuminance";

    const illuminanceEntity =
      getHaEntity(states, illuminanceEntityId);

    if (!illuminanceEntity) {
      debugLog(
        `Illuminance entity "${illuminanceEntityId}" was not found`
      );
    } else {
      const currentLux =
        Number(illuminanceEntity.state);

      if (!Number.isFinite(currentLux)) {
        debugLog(
          `Illuminance entity "${illuminanceEntityId}" ` +
          "does not have a numeric state",
          illuminanceEntity.state
        );
      } else {
        msg.current_lux = currentLux;

        if (currentLux > luxThreshold) {
          msg.decision = 299;
          msg.action = "off";

          appendDescription(
            `Turning Off ${msg.entityid} because ` +
            `illuminance (${currentLux}) is above the ` +
            `configured threshold of ${luxThreshold}.`
          );
        }
      }
    }
  }


  /* --------------------------------------------------------------
   * Final description details
   * -------------------------------------------------------------- */

  if (!msg.fullauto) {
    appendDescription(
      "The entity was last turned on manually."
    );
  }

  debugLog("Entity evaluation completed", {
    entityId: msg.entityid,
    action: msg.action,
    decision: msg.decision,
    description: msg.descr
  });

  return msg;

} catch (error) {
  const message =
    error && error.message
      ? error.message
      : String(error);

  return failSafe(
    `Unexpected function error: ${message}`,
    error && error.stack ? error.stack : undefined
  );
}

// Construct the relative time string from your variable
msg.payload = {
    relativeTime: msg.x_minutes + " minutes"
};
return msg;

const input = msg.entityid;

if (!input) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "missing msg.payload"
    });

    node.warn("No entity ID was supplied in msg.payload");
    return null;
}

// Access the Home Assistant state cache.
const ha = global.get("homeassistant");
const states = ha?.homeAssistant?.states || ha?.states;

if (!states) {
    node.status({
        fill: "red",
        shape: "ring",
        text: "HA states unavailable"
    });

    node.error(
        "Home Assistant states are not available. Enable Global Context Store in the Home Assistant server configuration.",
        msg
    );

    return null;
}

const individualEntities = new Set();
const processedGroups = new Set();
const unresolvedEntities = new Set();

function expandEntity(entityId) {
    if (typeof entityId !== "string") {
        return;
    }

    entityId = entityId.trim();

    if (!entityId) {
        return;
    }

    const stateObject = states[entityId];
    const members = stateObject?.attributes?.entity_id;

    // An entity with an entity_id array is treated as a group.
    if (Array.isArray(members) && members.length > 0) {
        // Prevent infinite recursion from circular group membership.
        if (processedGroups.has(entityId)) {
            return;
        }

        processedGroups.add(entityId);

        for (const member of members) {
            expandEntity(member);
        }

        return;
    }

    // Keep unresolved entities so Home Assistant can still attempt the action.
    if (!stateObject) {
        unresolvedEntities.add(entityId);
    }

    individualEntities.add(entityId);
}

const startingEntities = Array.isArray(input) ? input : [input];

for (const entityId of startingEntities) {
    expandEntity(entityId);
}

const entities = Array.from(individualEntities);

if (entities.length === 0) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "no entities found"
    });

    node.warn("No individual entities were found.");
    return null;
}

node.status({
    fill: "green",
    shape: "dot",
    text: `${entities.length} entities`
});

// Each array item is emitted as a separate Node-RED message.
const outputMessages = entities.map((entityId, index) => {
    // Clone the complete incoming msg object
    const newMsg = RED.util.cloneMessage(msg);
    // Save the original payload
    newMsg.group_source = input;

    // Replace payload with the individual entity
    newMsg.payload = entityId;

    newMsg.entity_id= entityId,
    newMsg.group_source= input,
    newMsg.entity_number= index + 1,
    newMsg.entity_count= entities.length,
    newMsg.unresolved= unresolvedEntities.has(entityId)

    return newMsg;    
});

return [outputMessages];

// Only allow the final processed entity message through.
if (msg.entity_number !== msg.entity_count) {
    node.status({
        fill: "blue",
        shape: "dot",
        text: `${msg.entity_number} of ${msg.entity_count}`
    });

    return null;
}

const source = msg.group_source;
const count = msg.entity_count;
const lastEntity = msg.entity_id;

msg.payload = {
    status: "complete",
    source: source,
    entity_count: count,
    last_entity: lastEntity,
    completed_at: new Date().toISOString()
};

msg.topic = "group_turn_off_complete";
msg.complete = true;

node.status({
    fill: "green",
    shape: "dot",
    text: `complete: ${count} entities`
});

return msg;

function ConvertSecondsToWords(totalSeconds) {
  var minutes = Math.floor(Number(totalSeconds) / 60);
  var seconds = Math.floor(Number(totalSeconds) % 60);

  // Handle singular/plural formatting
  var mDisplay = minutes > 0 ? minutes + (minutes === 1 ? " minute" : " minutes") : "";
  var sDisplay = seconds > 0 ? seconds + (seconds === 1 ? " second" : " seconds") : "";

  // Join parts with "and" if both exist
  var sentence = [mDisplay, sDisplay].filter(Boolean).join(" and ");

  return  sentence || "0 seconds";    
}

const now = Date.now();
const PRESENCE = env.get("PRESENCE");
const HasSensor = env.get("SENSOR");
const debug = Boolean(env.get("DEBUG"));
let totalPresenceMs = 0;
let x =0;
let OccupancyCount = 0;
const gHomeAssistant = global.get('homeassistant').homeAssistant;
msg.action='leave';
msg.descr='';
if (msg.reason != null || msg.reason != "") {
  msg.descr = msg.reason+" ";
}

msg.currently = gHomeAssistant.states[msg.entityid].state;
msg.fullauto = gHomeAssistant.states[msg.entityid].context.user_id == 'e7ab148881b7499f9b3189442f4e473c' // that is the nodered user

if (msg.currently=='on')
{
  if (debug == true) {
  //  node.warn('Checking '+msg.entityid);
  }      
  // entity was last turned on by the nodered user and therefore we shoud continue with auto turn off logic below
  if (msg.fullauto == false)
  {
    // if the entity was turned on manually then lets wait twice as long to turn it off
    msg.min_absence = msg.min_absence * 2;
    msg.min_on_time = msg.min_on_time * 2;
    // if these values are still 0 then set them to 10 minutes
    if (msg.min_absence == 0) { msg.min_absence = 10 * 60; } 
    if (msg.min_on_time == 0) { msg.min_on_time = 10 * 60; }

  }

  // 1. Get the last changed timestamp (ISO string)
  const lastChanged = gHomeAssistant.states[msg.entityid].last_changed;

  // 2. Convert timestamp and current time to Epoch milliseconds
  const lastChangedMs = new Date(lastChanged).getTime();
  const nowMs = Date.now();

  // 3. Calculate difference in seconds
  msg.on_for_seconds =(nowMs - lastChangedMs) / 1000;

  if (HasSensor != '') // Full Auto with a motion sensor
  {
      // msg.Occupied can be set to "on" already and in that case just leave it
      // sometimes the timing is just right that ahead of this node, Occupied is true to it takes a path that does not get history records
      if (msg.Occupied!='on'){
        msg.Occupied = gHomeAssistant.states[msg.sensor].state
      }  

      // if a room has had no motion for the last x miutes, there may be no history records to examine
      if (msg.Occupied == 'on') {
        // 1. Get the last changed timestamp (ISO string)
        const lastChanged = gHomeAssistant.states[msg.sensor].last_changed;

        // 2. Convert timestamp and current time to Epoch milliseconds
        const lastChangedMs = new Date(lastChanged).getTime();
        const nowMs = Date.now();

        // 3. Calculate difference in seconds
        const diffSeconds = (nowMs - lastChangedMs) / 1000;
        msg.SecondsofOccupancy =(nowMs - lastChangedMs) / 1000;
        msg.OccupancyCount = 1;
        msg.SecondsSinceOccupancy = 0;
      }
      else { // unoccupied Room
        // 1. Get the last changed timestamp (ISO string)
        const lastChanged = gHomeAssistant.states[msg.sensor].last_changed;

        // 2. Convert timestamp and current time to Epoch milliseconds
        const lastChangedMs = new Date(lastChanged).getTime();
        const nowMs = Date.now();

        // 3. Calculate difference in seconds
        const diffSeconds = (nowMs - lastChangedMs) / 1000;
        msg.SecondsSinceOccupancy = (nowMs - lastChangedMs) / 1000;
        msg.SecondsofOccupancy = 0
        msg.OccupancyCount = 0;
      }


      if (msg.Occupied == 'on'){
        if (debug == true) {
          node.warn('Occupied');
        } 
        msg.action='leave';
        msg.descr = msg.descr + 'Sensor: ' + msg.sensor+' indcates occupied.'
      }
      else { // unoccupied Room, need to be sure the room has ben unoccupied long enough
        if (debug == true) {
          node.warn('Unoccupied');
      } 

      // now lets total up the amount of presence over the last x minutes
      const WINDOW_MS = msg.x_minutes * 60 * 1000;
      const now = Date.now();
      const windowStart = now - WINDOW_MS;

      let history = msg.payload;
      if (!Array.isArray(history)) {
        node.error("Expected Home Assistant history array in msg.payload", msg);
        return null;
      }

      // Normalize and sort records
      let records = history
        .filter(item => item && (item.last_changed || item.last_updated))
        .map(item => ({ state: String(item.state || "").toLowerCase(),
        ts: new Date(item.last_changed || item.last_updated).getTime()
        }))
        .filter(item => !isNaN(item.ts))
        .sort((a, b) => a.ts - b.ts);

        // Only keep records that could affect the last 10 minutes
        records = records.filter(r => r.ts <= now);

        // Find the state at the start of the window
        let stateAtWindowStart = "off";
        for (const r of records) {
          if (r.ts <= windowStart) {
            stateAtWindowStart = r.state;
          } else {
            break;
          }
        }

        // Keep records inside the window
        let windowRecords = records.filter(r => r.ts >= windowStart);

        // Insert a synthetic starting record so duration is calculated correctly
        windowRecords.unshift({
          state: stateAtWindowStart,
          ts: windowStart
        });

        let totalPresenceMs = 0;

        for (let i = 0; i < windowRecords.length; i++) {
          const current = windowRecords[i];
          const next = windowRecords[i + 1];
          const endTime = next ? next.ts : now;

          const isOn = current.state === "on" || current.state === "detected" || current.state === "true";

          if (isOn && endTime > current.ts) {
            if (debug == true) {
           //   let s = msg.sensor + ': on from ' + new Date( current.ts).toLocaleString() + ' to  ' + new Date(endTime).toLocaleString()+ ' = '+ ((endTime - current.ts)/1000) + ' seconds'
           //   node.warn(s)
            }
            if (PRESENCE === 'TOTAL') {
              // get total seconds of occupancy
              totalPresenceMs += (endTime - current.ts);
            }
            // OR
            // Use only the longest single period of occupancy
            else if (PRESENCE === 'LONGEST') {
              if ((endTime - current.ts) >= totalPresenceMs){
                totalPresenceMs = (endTime - current.ts);
              }
            }
            else if (PRESENCE === 'AVG') {
              totalPresenceMs  =(endTime - current.ts);
            }
            else if (PRESENCE === 'LAST') {
              totalPresenceMs = (endTime - current.ts);
            }
            OccupancyCount += 1

          }
        }
        if ((totalPresenceMs>>0) && (PRESENCE === 'AVG')) {
          totalPresenceMs = totalPresenceMs / OccupancyCount
        }  

        msg.SecondsofOccupancy = parseFloat((totalPresenceMs / 1000).toFixed(0));
        msg.OccupancyCount = OccupancyCount;

        // if the room is clear now and has been more clear than occupied over the last 10 minutes, turn off the lights
        // 5 mins occupied require 5 minutes clear before turning off
        // 1 min of occupation, require 1 minute of clear before turning off

        // have decided to leave the entity on
        if ((msg.action == "leave") && (msg.currently == "on")){
          if (msg.Occupied=='on') {
            msg.descr = "Leaving " + msg.entityid + " on as the room is currently occupied.";
          }
          else
          {
            if (((Number(msg.min_on_time) == 0) || ((Number(msg.on_for_seconds) > Number(msg.min_on_time))))
              && ((Number(msg.min_absence) == 0) || ((Number(msg.SecondsSinceOccupancy) > Number(msg.min_absence)))))
            {
              msg.decision = 218;
              msg.action = 'off';
              msg.descr = "Turning Off " + msg.entityid + ". No motion for " + ConvertSecondsToWords(msg.SecondsSinceOccupancy)
              if ((Number(msg.min_on_time) > 0) && (Number(msg.on_for_seconds) >= Number(msg.min_on_time))) {
                msg.descr = msg.descr + " and the minimum on time (" + ConvertSecondsToWords(msg.min_on_time) + ") has been met"
              }
              if ((Number(msg.min_absence) > 0) && (Number(msg.SecondsSinceOccupancy) >= Number(msg.min_absence))) {
                msg.descr = msg.descr + " and the minimum absence (" + ConvertSecondsToWords(msg.min_absence) + ") has been met"
              }
              msg.descr = msg.descr + ".";

            }
            else
            {
              msg.decision = 233;
              msg.descr = "Leaving " + msg.entityid + " on. No motion for " + ConvertSecondsToWords(msg.SecondsSinceOccupancy);
              if ((Number(msg.on_for_seconds) > 0) && (Number(msg.on_for_seconds) < Number(msg.min_on_time))) {
                msg.descr = msg.descr + " and the minimum on time (" + ConvertSecondsToWords(msg.min_on_time) + ") has NOT been met"
              }
              else if ((Number(msg.min_on_time) > 0) && (Number(msg.on_for_seconds) < Number(msg.min_on_time))) {
                msg.descr = msg.descr + " and the minimum on time (" + ConvertSecondsToWords(msg.min_on_time) + ") has NOT been met"
              }
              if ((Number(msg.min_absence) > 0) && (Number(msg.SecondsSinceOccupancy) < Number(msg.min_absence))) {
                msg.descr = msg.descr + " and the minimum absence (" + ConvertSecondsToWords(msg.min_absence) + ") has NOT been met"
              }

              msg.descr = msg.descr + ".";

            }

          }

        } 
//        else  // have decided to leave the entity off
//        {
//          if ((msg.action == "leave") && (msg.currently == "off")){
//              msg.descr = "Leaving " + msg.entityid + " off."
//          }  
//        }

        var totalSeconds = Number(totalPresenceMs)/1000;
        if ((totalSeconds/60) >> Number(msg.x_minutes)){
          totalSeconds = Number(msg.x_minutes)*60
        }    
        msg.sentence = ConvertSecondsToWords(Number(totalSeconds));

        if (msg.sentence !="") {
          msg.descr = msg.descr + " " + PRESENCE + " presence was " + msg.sentence+"."
        } 
        else {
          msg.descr = msg.descr + " There was no "+ PRESENCE + " presence determined."
        }  
        if (msg.fullauto == false) {
          msg.descr = msg.descr + " Entity was last turned on Manually."

        }

      }

    } 
    else { // no motion sensor provided
      if (debug == true) {
        node.warn('No Sensor provided');
      }      
      // Convert to minutes and round
      // seconds of occupancy
      // Retrieve last_changed for a specific entity

      const lastChanged = gHomeAssistant.states[msg.entityid].last_changed;
      var totalSeconds = (Date.now() - new Date(lastChanged).getTime())/1000;
      msg.sentence = ConvertSecondsToWords(totalSeconds);


      if (debug == true) {
        node.warn('action: '+msg.action);
      }
      if (msg.action == 'leave') { // no action yet to be take from prior logic
        // check to see if its has been on long enough, Some devices turn off regardless of presense like fans and diffusers
        if ((msg.currently == 'on') && (Number(msg.min_on_time) >= 0) && (Number(msg.on_for_seconds) >= Number(msg.min_on_time))){
          // turn off since its been on past the Min_on_time and the room is not occupied
          msg.decision = 274;
          msg.action = 'off';
          msg.sentence = ConvertSecondsToWords(Number(msg.on_for_seconds));
          msg.descr = msg.descr + "Turning Off " + msg.entityid + " as it has been on for " + msg.sentence + " exceeding the max on time of "+ConvertSecondsToWords(Number(msg.min_on_time));
          if (msg.fullauto == false) {
            msg.descr = msg.descr + " Entity was last turned on Manually."

          }
        }
        else{
          msg.decision = 284;
          msg.descr = msg.descr + "Leaving " + msg.entityid + " " + msg.currently+ " as it has only been "+msg.currently+" " + msg.sentence;
          if (msg.sentence !="") {
            msg.descr = msg.descr + " and needs to be on for at least " +ConvertSecondsToWords(Number(msg.min_on_time))+"."
          } 
          if (msg.fullauto == false){
            msg.descr = msg.descr + " Entity was last turned on Manually."

          }
        }  
      }
    }
    // WE MAY WANT TO TURN OFF DUE TO THE ILLUMINANCE LEVELS
  if ((msg.fullauto == true) && (msg.currently == 'on') && (msg.action == 'leave') && (Number(msg.is_dark_lux) >> 0)) {
    if (gHomeAssistant.states['sensor.illuminance'].state > Number(msg.is_dark_lux)) {
      msg.decision = 299;
      msg.action = 'off';
      msg.descr = msg.descr + "Turning Off " + msg.entityid + " on as Illuminace (" + gHomeAssistant.states['sensor.illuminance'].state + ") has climbed above " + msg.is_dark_lux;
    }

  }

}
else
{
  msg.currently = 'off';
  msg.on_for_seconds = 0;
  msg.descr = msg.descr + "Leaving " + msg.entityid + " off";
}


return msg;
